const items = $input.all();
const countryRestrictionPatterns = [
  /\bUS[- ]?only\b/i, /\bUSA?\s+resident/i,
  /\bmust be (authorized|eligible) to work in the (us|united states|uk|eu)\b/i,
  /\bno\s+(h1b|sponsorship|visa sponsorship)\b/i,
  /\b401\(?k\)?\b/i, /\bHSA\b/i, /\beu\s+only\b/i, /\bindia\s+only\b/i,
  /\bpan[- ]india\b/i, /\bcountries of europe or ukraine\b/i,
  /\bmust be based in\b/i, /\brelocat(e|ion) to\b/i,
  /\bwithin \d+ (hours?|hrs?) of (est|pst|cst|gmt)\b/i
];
const seniorityRedFlags = [
  /\bsenior\b/i, /\bstaff\b/i, /\blead\s+(engineer|developer)\b/i,
  /\bprincipal\b/i, /\b(5|6|7|8|9|10)\+?\s*years?\b/i,
  /\bat least (4|5|6|7|8) years?\b/i
];
const degreeRedFlags = [
  /\brequires? a (bachelor|master|phd)('s)? degree\b/i,
  /\bdegree in computer science required\b/i
];
const stackRedFlags = [
  /\bpython\s+(is\s+)?(required|core|primary|expertise)\b/i,
  /\bexpertise in python\b/i, /\bflutter\b/i, /\bdart\b/i
];
function checkFlags(text, patterns) {
  if (!text) return [];
  return patterns.filter(p => p.test(text)).map(p => p.source);
}
function stripBoilerplate(text) {
  if (!text) return text;
  const contentMarkers = [
    /##\s*Description/i,
    /##\s*About the [Rr]ole/i,
    /\[Skip to content\]/i,
    /#\s*Careers at/i
  ];
  let earliestIndex = -1;
  for (const marker of contentMarkers) {
    const match = text.match(marker);
    if (match && match.index !== undefined) {
      if (earliestIndex === -1 || match.index < earliestIndex) {
        earliestIndex = match.index;
      }
    }
  }
  if (earliestIndex > -1) {
    return text.slice(earliestIndex).trim();
  }
  return text;
}
return items.map(item => {
  const rawCombined = item.json.title + ' ' + (item.json.description || '');
  const text = stripBoilerplate(rawCombined);
  const countryFlags = checkFlags(text, countryRestrictionPatterns);
  const seniorityFlags = checkFlags(text, seniorityRedFlags);
  const degreeFlags = checkFlags(text, degreeRedFlags);
  const stackFlags = checkFlags(text, stackRedFlags);
  const totalFlags = countryFlags.length + seniorityFlags.length + degreeFlags.length + stackFlags.length;
  return {
    json: {
      company: item.json.name,
      careersUrl: item.json.careersUrl || item.json.applicationLink || item.json.apply_url || item.json.url || null,
      raw_text: text.slice(0, 8000),
      pre_filter_verdict: totalFlags === 0 ? 'PASSES_KEYWORD_FILTER' : 'FLAGGED',
      flags_found: { country: countryFlags, seniority: seniorityFlags, degree: degreeFlags, stack: stackFlags }
    }
  };
});

const items = $input.all();
const originalData = $('Filter - Red Flag Keywords').all();

return items.map((item, index) => {
  let parsed;
  try {
    const rawText = item.json.choices?.[0]?.message?.content || '{}';
    parsed = JSON.parse(rawText);
  } catch (e) {
    parsed = { company: 'unknown', verdict: 'PARSE_ERROR', matching_role_title: null, reason: 'OpenAI response was not valid JSON - check manually' };
  }
  const match = originalData[index];
  parsed.careersUrl = match?.json?.careersUrl || null;
  parsed.originalName = match?.json?.name || parsed.company;
  return { json: parsed };
});

// Only pass through NEW matches worth reporting.
// Filters out NO_MATCH and PARSE_ERROR so the report only shows real leads.
const items = $input.all();
return items.filter(item => 
  item.json.verdict === 'MATCH' || item.json.verdict === 'UNCLEAR_NEEDS_HUMAN_CHECK'
);

const items = $input.all();
const date = new Date().toISOString().split('T')[0];

let report = `# Wayfind Report - ${date}\n\n`;
report += `${items.length} potential match(es) found this run.\n\n`;

items.forEach(item => {
  const j = item.json;
  report += `## ${j.company}\n`;
  report += `- **Verdict:** ${j.verdict}\n`;
  report += `- **Role:** ${j.matching_role_title || 'not specified'}\n`;
  report += `- **Apply:** ${j.careersUrl || 'link not available'}\n`;
  report += `- **Reason:** ${j.reason}\n\n`;
});

if (items.length === 0) {
  report += 'No new matches this run.\n';
}

return [{ json: { report_markdown: report, date } }];

const allInput = $input.all();

let remoteOkJobs = [];
let remotiveJobs = [];
let himalayasJobs = [];
let workingNomadsJobs = [];
let wwrJobs = [];
let jobicyJobs = [];
let arbeitnowJobs = [];
let joobleJobs = [];
let findworkJobs = [];
let reedJobs = [];
let adzunaJobs = [];
let startupJobsItems = [];
let remoteLandersJobs = [];
let hnStory = null;

for (const item of allInput) {
  const data = item.json;

  if (data.company) {
    remoteOkJobs.push(data);

  } else if (data.jobs && Array.isArray(data.jobs)) {
    const firstJob = data.jobs[0] || {};
    if (firstJob.applyUrl !== undefined && firstJob.slug !== undefined) {
      remoteLandersJobs = data.jobs;
    } else if (firstJob.jobTitle !== undefined) {
      jobicyJobs = data.jobs;
    } else if (firstJob.snippet !== undefined && firstJob.link !== undefined) {
      joobleJobs = data.jobs;
    } else if (firstJob.companyName !== undefined) {
      himalayasJobs = data.jobs;
    } else {
      remotiveJobs = data.jobs;
    }

  } else if (data.results && Array.isArray(data.results)) {
    const firstResult = data.results[0] || {};
    if (firstResult.jobTitle !== undefined && firstResult.employerName !== undefined) {
      reedJobs = data.results;
    } else if (firstResult.redirect_url !== undefined) {
      adzunaJobs = data.results;
    } else if (firstResult.role !== undefined) {
      findworkJobs = data.results;
    }

  } else if (data.data && Array.isArray(data.data)) {
    arbeitnowJobs = data.data;

  } else if (data.company_name !== undefined && data.url !== undefined) {
    workingNomadsJobs.push(data);

  } else if (data.children !== undefined && Array.isArray(data.children) && data.type === 'story') {
    hnStory = data;

  } else if (data.guid !== undefined && data.isoDate !== undefined) {
    if (data.categories !== undefined && Array.isArray(data.categories)) {
      startupJobsItems.push(data);
    } else {
      wwrJobs.push(data);
    }
  }
}

const CUTOFF_DAYS = 30;
const cutoffMs = Date.now() - CUTOFF_DAYS * 24 * 60 * 60 * 1000;

function isFresh(dateValue) {
  if (dateValue === undefined || dateValue === null || dateValue === '') return true; // fail open if no date available
  const t = new Date(dateValue).getTime();
  if (isNaN(t)) return true; // fail open if unparseable
  return t >= cutoffMs;
}

function titleOk(title) {
  const t = (title || '').toLowerCase();
  const senior = /senior|staff|principal|director|manager/.test(t);
  const relevant = /engineer|developer|full.?stack|frontend|backend/.test(t);
  return !senior && relevant;
}

function stripHtml(text) {
  return (text || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&#x27;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&#x2F;/g, '/')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ---- Original 5 sources ----

const fromRemoteOk = remoteOkJobs
  .filter(job => job.company && (!job.location || job.location.trim() === '') && titleOk(job.position) && isFresh(job.date)) // "date" confirmed real tonight
  .map(job => ({ json: { name: job.company, careersUrl: job.apply_url, title: job.position, description: job.description || '' } }));

const fromRemotive = remotiveJobs
  .filter(job => titleOk(job.title)) // no freshness filter — field name never confirmed against real Remotive data
  .map(job => ({ json: { name: job.company_name, careersUrl: job.url, title: job.title, description: job.description || '' } }));

const fromHimalayas = himalayasJobs
  .filter(job => titleOk(job.title)) // no freshness filter — field name never confirmed against real Himalayas data
  .map(job => ({
    json: {
      name: job.companyName || 'Unknown (Himalayas)',
      careersUrl: job.applicationLink || job.guid || null,
      title: job.title,
      description: job.excerpt || ''
    }
  }));

const fromWorkingNomads = workingNomadsJobs
  .filter(job => titleOk(job.title) && isFresh(job.pub_date)) // "pub_date" confirmed real via direct API fetch tonight
  .map(job => ({
    json: {
      name: job.company_name || 'Unknown (Working Nomads)',
      careersUrl: job.url,
      title: job.title,
      description: `Location: ${job.location || 'not specified'}\n\n${job.description || ''}`
    }
  }));

const fromWWR = wwrJobs
  .filter(job => {
    const parts = (job.title || '').split(':');
    const positionTitle = parts.length > 1 ? parts.slice(1).join(':').trim() : job.title;
    return titleOk(positionTitle) && isFresh(job.isoDate); // "isoDate" confirmed real in RSS output tonight
  })
  .map(job => {
    const parts = (job.title || '').split(':');
    const company = parts.length > 1 ? parts[0].trim() : 'Unknown (WWR)';
    const positionTitle = parts.length > 1 ? parts.slice(1).join(':').trim() : job.title;
    return {
      json: {
        name: company,
        careersUrl: job.link,
        title: positionTitle,
        description: job.contentSnippet || ''
      }
    };
  });

// ---- 9 new sources ----

const fromJobicy = jobicyJobs
  .filter(job => titleOk(job.jobTitle) && isFresh(job.pubDate)) // "pubDate" confirmed real via direct API fetch tonight
  .map(job => ({
    json: {
      name: job.companyName || 'Unknown (Jobicy)',
      careersUrl: job.url,
      title: job.jobTitle,
      description: job.jobExcerpt || job.jobDescription || ''
    }
  }));

const fromArbeitnow = arbeitnowJobs
  .filter(job => job.remote === true && titleOk(job.title)) // no freshness filter — field name never confirmed against real Arbeitnow data
  .map(job => ({
    json: {
      name: job.company_name || 'Unknown (Arbeitnow)',
      careersUrl: job.url,
      title: job.title,
      description: job.description || ''
    }
  }));

const KNOWN_AGGREGATORS = ['powertofly', 'linkedin', 'indeed', 'ziprecruiter', 'glassdoor', 'monster', 'careerbuilder'];

function isAggregatorName(name) {
  const n = (name || '').toLowerCase();
  return KNOWN_AGGREGATORS.some(agg => n.includes(agg));
}

const fromJooble = joobleJobs
  .filter(job => titleOk(job.title) && isFresh(job.updated)) // "updated" confirmed real in n8n output tonight — "jobAge" is NOT a real field, only appears inside the URL string
  .map(job => {
    const rawName = job.company || 'Unknown (Jooble)';
    const name = isAggregatorName(rawName)
      ? `Unclear — posted via ${rawName}, actual employer may differ (see description)`
      : rawName;
    return {
      json: {
        name,
        careersUrl: job.link,
        title: job.title,
        description: job.snippet || ''
      }
    };
  });

const fromFindwork = findworkJobs
  .filter(job => titleOk(job.role)) // no date field ever identified for Findwork
  .map(job => ({
    json: {
      name: job.company_name || 'Unknown (Findwork)',
      careersUrl: job.url,
      title: job.role,
      description: job.text || (job.keywords ? job.keywords.join(', ') : '')
    }
  }));

const fromReed = reedJobs
  .filter(job => titleOk(job.jobTitle)) // no freshness filter — field name documented but never confirmed against real Reed data
  .map(job => ({
    json: {
      name: job.employerName || 'Unknown (Reed)',
      careersUrl: job.jobUrl,
      title: job.jobTitle,
      description: `Location: ${job.locationName || 'not specified'}\n\n${job.jobDescription || ''}`
    }
  }));

const fromAdzuna = adzunaJobs
  .filter(job => titleOk(job.title) && isFresh(job.created)) // "created" confirmed real via direct API fetch tonight
  .map(job => ({
    json: {
      name: (job.company && job.company.display_name) || 'Unknown (Adzuna)',
      careersUrl: job.redirect_url,
      title: job.title,
      description: `Location: ${(job.location && job.location.display_name) || 'not specified'}\n\n${job.description || ''}`
    }
  }));

const fromStartupJobs = startupJobsItems
  .filter(job => {
    const parts = (job.title || '').split(' at ');
    const roleTitle = parts.length > 1 ? parts[0].trim() : job.title;
    return titleOk(roleTitle) && isFresh(job.isoDate); // "isoDate" confirmed real in RSS output tonight
  })
  .map(job => {
    const parts = (job.title || '').split(' at ');
    const roleTitle = parts.length > 1 ? parts[0].trim() : job.title;
    const company = parts.length > 1 ? parts.slice(1).join(' at ').trim() : 'Unknown (Startup Jobs)';
    return {
      json: {
        name: company,
        careersUrl: job.link,
        title: roleTitle,
        description: job.contentSnippet || ''
      }
    };
  });

const fromRemoteLanders = remoteLandersJobs
  .filter(job => job.location === 'Worldwide' && titleOk(job.title) && isFresh(job.postedDate)) // "postedDate" confirmed real in official API docs tonight
  .map(job => ({
    json: {
      name: job.company || 'Unknown (Remote Landers)',
      careersUrl: job.applyUrl || job.url,
      title: job.title,
      description: `${job.level ? 'Level: ' + job.level + '. ' : ''}${job.salary ? 'Salary: ' + job.salary + '. ' : ''}`.trim()
    }
  }));

const fromHN = (hnStory && Array.isArray(hnStory.children) ? hnStory.children : [])
  .filter(job => job.text) // always current month by construction — no separate freshness check needed
  .map(job => ({ clean: stripHtml(job.text), raw: job }))
  .filter(j => titleOk(j.clean))
  .map(j => {
    const parts = j.clean.split('|').map(p => p.trim());
    const company = parts.length > 1 ? parts[0] : 'Unknown (HN Who Is Hiring)';
    const roleTitle = parts.length > 1 ? parts[1] : j.clean.slice(0, 80);
    return {
      json: {
        name: company,
        careersUrl: `https://news.ycombinator.com/item?id=${j.raw.id}`,
        title: roleTitle,
        description: j.clean
      }
    };
  });

return [
  ...fromRemoteOk,
  ...fromRemotive,
  ...fromHimalayas,
  ...fromWorkingNomads,
  ...fromWWR,
  ...fromJobicy,
  ...fromArbeitnow,
  ...fromJooble,
  ...fromFindwork,
  ...fromReed,
  ...fromAdzuna,
  ...fromStartupJobs,
  ...fromRemoteLanders,
  ...fromHN
];

const newJobs = $('Filter Real Jobs').all();
const alreadyChecked = $input.all().map(item => item.json.company);

const filtered = newJobs.filter(job => !alreadyChecked.includes(job.json.name));
return filtered;
